#!/usr/bin/python3
# This test decoder accepts only the unfiltered RGBA PNGs generated by model3d_protocol.py.
import binascii
from pathlib import Path
import struct
import sys
import zlib

source, output, bound = Path(sys.argv[1]), Path(sys.argv[2]), int(sys.argv[3])
data = source.read_bytes()
assert data[:8] == b"\x89PNG\r\n\x1a\n"
width, height, bits, color, compression, filtering, interlace = struct.unpack_from(">IIBBBBB", data, 16)
assert (bits, color, compression, filtering, interlace) == (8, 6, 0, 0, 0)
# The protocol test's marker sits beside this file outside the jail, so seeing it means the decoder ran unsandboxed.
jailed = not Path(__file__).with_name(".flea-test-sandbox").exists()
# Sample input: the 8-byte PNG signature, then chunks of u32be length, 4-byte type, payload and u32be CRC32 of type and payload.
at = 8
compressed = bytearray()
while at < len(data):
    count = struct.unpack_from(">I", data, at)[0]
    kind = data[at + 4:at + 8]
    payload = data[at + 8:at + 8 + count]
    crc = struct.unpack_from(">I", data, at + 8 + count)[0]
    assert binascii.crc32(kind + payload) == crc
    if kind == b"IDAT":
        compressed.extend(payload)
    at += count + 12
raw = zlib.decompress(compressed)
pitch = width * 4 + 1
assert len(raw) == pitch * height
assert all(raw[y * pitch] == 0 for y in range(height))
scale = min(1, bound / max(width, height))
w, h = max(1, int(width * scale)), max(1, int(height * scale))
resized = bytearray()
for y in range(h):
    resized.append(0)
    for x in range(w):
        offset = (y * height // h) * pitch + 1 + (x * width // w) * 4
        resized.extend(raw[offset:offset + 4])


# Sample output: big-endian length, four chunk-type bytes, payload, then the CRC32 of type and payload.
def chunk(kind, payload):
    return struct.pack(">I", len(payload)) + kind + payload + struct.pack(">I", binascii.crc32(kind + payload))


encoded = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
encoded += chunk(b"tEXt", b"Model3D-Test-Decoder\0" + (b"sandboxed" if jailed else b"outside-sandbox")) + chunk(b"IDAT", zlib.compress(resized)) + chunk(b"IEND", b"")
with output.open("wb") as file:
    file.write(encoded)
